def window_sums(nums, k):
    if k <= 0 or k > len(nums):
        return []
    s = sum(nums[:k])
    out = [s]
    for i in range(k, len(nums)):
        s += nums[i] - nums[i-k]
        out.append(s)
    return out

def binary_search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

