    perm, temp, out = set(), set(), []

    def visit(v):
        if v in perm:
            return
        if v in temp:
            raise ValueError('cycle')
        temp.add(v)
        for w in graph.get(v, []):
            visit(w)
        temp.remove(v)
        perm.add(v)
        out.append(v)

    for v in graph:
        visit(v)
    out.reverse()
    return out

